'use strict';
const $=(q,root=document)=>root.querySelector(q), $$=(q,root=document)=>[...root.querySelectorAll(q)];
const h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Number(n||0).toLocaleString('fr-CA'), files={plan:'Plan de structure',atelier:'Dessin d’atelier'};
const families={fondation:'Fondation',colonne:'Colonne',poutre:'Poutre',mur_refend:'Mur de refend',dalle:'Dalle',inconnu:'À identifier'};
const state={overview:null,route:'projects',project:null,run:null,results:[],resultTotal:0,sheets:[],filter:{q:'',status:'',family:'',sheet:'',review:'',offset:0},docRole:'all',docId:null,docPage:1,docZoom:70,reportInfo:null,selectedSheets:new Set(),reportSheet:null,reportPage:1,reportPages:1,detail:null,detailIndex:0,zoom:100,candidate:0,uploadPlans:[],uploadShop:[],uploadStep:1,controller:null,routeId:0,stoppedJob:null,projectTab:'Documents'};
let pollTimer,searchTimer,toastTimer,uploadController;
const runDate=d=>new Date(d).toLocaleString('fr-CA',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'});
function api(path,options={}){return fetch('/api'+path,{...options,headers:{'X-Concorde-Request':'1',...(options.body instanceof FormData?{}:options.body?{'Content-Type':'application/json'}:{}),...options.headers}}).then(async r=>{if(!r.ok){let m=`Erreur ${r.status}`;try{m=(await r.json()).detail||m}catch{}throw Error(m)}return options.raw?r:r.json()})}
function toast(msg){const t=$('#toast');t.textContent=msg;t.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.hidden=true,4200)}
function pageHeading(title,desc,action=''){return `<div class="heading"><div><div class="eyebrow">CONCORDE / RÉVISION DES STRUCTURES</div><h1>${h(title)}</h1><p>${h(desc)}</p></div>${action}</div>`}
function status(s){const map={conforme:['Accord partiel','partial'],non_conforme:['Écart proposé','proposed'],a_verifier:['À vérifier','check'],confirme:['Révision confirmée','confirmed'],rejete:['Proposition rejetée','rejected'],completed:['Analyse terminée','confirmed'],running:['En cours','check'],queued:['En attente','check'],failed:['Échec','proposed'],interrupted:['Interrompue','check']};const [label,cls]=map[s]||[s||'À vérifier','check'];return `<span class="status ${cls}">${h(label)}</span>`}
function routeParts(){const bits=location.hash.slice(1).split('/').filter(Boolean);return {page:bits[0]||'projects',id:bits[1]||''}}
function projectById(id){return state.overview?.projects.find(x=>x.id===id)}
function completedRuns(projectId){return (state.overview?.jobs||[]).filter(j=>j.status==='completed'&&(!projectId||j.project_id===projectId))}
function activeJob(){return state.overview?.jobs.find(j=>['running','queued'].includes(j.status))}
async function loadOverview(){state.overview=await api('/overview');$('#nav-project-count')?.replaceChildren(document.createTextNode(fmt(state.overview.projects.length)));return state.overview}
function setTitle(title){document.title=`Concorde · ${title}`}
function updateShell(page,title){document.body.dataset.view=page;$$('[data-nav]').forEach(a=>{const active=a.dataset.nav===page||(page==='project'&&a.dataset.nav==='projects')||(page==='detail'&&a.dataset.nav==='review');a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});$('#crumb').innerHTML=`<span>Concorde</span> <span aria-hidden="true">/</span> <strong>${h(title)}</strong>`;setTitle(title)}
function imagePreview(doc,page=1,scale=.7,box='',full=false){return `/api/documents/${encodeURIComponent(doc)}/preview?page=${page}&scale=${scale}${box?`&box=${encodeURIComponent(box)}`:''}${full?'&full=true':''}`}
function projectThumb(p){return p.documents?.length?`<img class="plan-thumb" src="${imagePreview(p.documents[0],1,.35)}" alt="Aperçu du premier plan de ${h(p.name)}" loading="lazy">`:''}
function overviewCounts(){const jobs=state.overview.jobs,run=jobs.find(j=>j.status==='completed'),stats=run?.statistics||{};let pending=run?stats.counts.a_verifier+stats.counts.non_conforme:0;return {pending,run}}
function renderProjects(){const o=state.overview,counts=overviewCounts(),p=counts.run?projectById(counts.run.project_id):null;updateShell('projects','Vos projets');const recent=state.overview.jobs[0];$('#view').innerHTML=pageHeading('Vos projets','Retrouvez vos dossiers et les révisions à poursuivre.',`<button class="button primary" data-action="import">＋ Importer un projet</button>`)+(p&&counts.pending?`<section class="card featured"><div>${projectThumb(p)}</div><div><div class="eyebrow">RÉVISION RÉCENTE ${status(recent?.status||'completed')}</div><h2>${h(p.name)}</h2><div class="featured-meta"><span>${fmt(p.documents.length)} documents</span><span>${fmt(p.pages)} pages</span><span>Dernière analyse : ${h(runDate(counts.run.created_at))}</span></div><small class="muted">Comparer les armatures entre plans et dessins d’atelier.</small></div><div class="featured-action"><strong>${fmt(counts.pending)}</strong><small>observations à examiner</small><button class="button primary" data-open-run="${counts.run.id}">Reprendre la révision →</button></div></section>`:'')+`<div class="metrics"><div class="metric"><div class="label">Projets</div><div class="value">${fmt(o.projects.length)}</div><div class="caption">Dossiers locaux</div></div><div class="metric"><div class="label">Documents sources</div><div class="value">${fmt(o.projects.reduce((n,x)=>n+x.documents.length,0))}</div><div class="caption">Plans et dessins d’atelier</div></div><div class="metric"><div class="label">Analyses terminées</div><div class="value">${fmt(o.jobs.filter(j=>j.status==='completed').length)}</div><div class="caption">Rapports conservés localement</div></div></div><div class="section-head"><h2>Bibliothèque de projets</h2><small>${fmt(o.projects.length)} DOSSIERS</small></div><section class="card"><div class="table-wrap"><div class="project-row"><div>Projet</div><div>Documents</div><div>Dernière analyse</div><div>État</div><div>Action</div></div>${o.projects.map(x=>{const last=o.jobs.find(j=>j.project_id===x.id),done=last?.status==='completed';return `<div class="project-row"><div class="project-cell">${projectThumb(x)}<span><strong>${h(x.name)}</strong><small>${fmt(x.pages)} pages · local</small></span></div><div>${fmt(x.documents.length)} PDF</div><div>${last?h(runDate(last.created_at)):'Aucune analyse'}</div><div>${status(last?.status||'queued')}</div><div><button class="button compact" data-project="${h(x.id)}">Ouvrir</button></div></div>`}).join('')||`<div class="empty"><h2>Aucun projet pour l’instant</h2><p>Importez des plans de structure et les dessins d’atelier correspondants pour commencer.</p><button class="button primary" data-action="import">Importer les PDF</button></div>`}</div></section><section class="activity-list"><div class="section-head"><h2>Activité récente</h2><small>ANALYSES LOCALES</small></div><section class="card">${o.jobs.slice(0,5).map(j=>`<div class="activity-row"><span aria-hidden="true">◷</span><div class="grow"><strong>${h(j.project_name)}</strong><small>${h(runDate(j.created_at))} · ${j.status==='completed'?`${fmt(j.statistics.annotations)} annotations lues`:`${fmt(j.current)} / ${fmt(j.total)} pages · ${h(j.message)}`}</small></div>${status(j.status)}${j.status==='completed'?`<button class="button compact" data-open-run="${j.id}">Révision →</button>`:''}</div>`).join('')||`<div class="activity-row">Vos analyses apparaîtront ici.</div>`}</section></section>`}
function renderUpload(){updateShell('projects','Importer un projet');const filesHtml=(arr,key)=>arr.map((f,i)=>`<div class="file-row"><span aria-hidden="true">🗎</span><span title="${h(f.name)}">${h(f.name)}</span><small>${fmt(f.pages||0)} pages · ${ (f.size/1048576).toFixed(1)} Mo</small><button type="button" data-remove-file="${key}" data-index="${i}" aria-label="Retirer ${h(f.name)}">×</button></div>`).join('');$('#view').innerHTML=pageHeading('Importer un projet','Ajoutez les plans de référence et les dessins de fabrication.')+`<form id="upload-form" novalidate><div class="field upload-name-field"><label for="project-name">Nom du projet</label><input class="input" id="project-name" name="name" required maxlength="80" placeholder="Ex. Résidence Saint-Laurent" value="${h(state.project||'')}"></div><div class="stepper"><div class="step ${state.uploadStep===1?'active':'done'}"><i>1</i>Documents</div><div class="step ${state.uploadStep===2?'active':state.uploadStep===3?'done':''}"><i>2</i>Vérification</div><div class="step ${state.uploadStep===3?'active':''}"><i>3</i>Analyse</div></div>${state.uploadStep===1?`<div class="upload-grid">${[['plan','Plans de structure','Documents de référence · conçus par l’ingénieur','cyan',state.uploadPlans],['atelier','Dessins d’atelier','Documents de fabrication','orange',state.uploadShop]].map(([key,title,desc,color,arr])=>`<section class="upload-card ${color==='orange'?'orange':''}"><div class="upload-head">▧ &nbsp; ${title}</div><small class="muted">${desc}</small><label class="dropzone" data-drop="${key}"><strong>Glissez les PDF ici</strong><span>ou choisissez les fichiers</span><span class="button compact">Choisir les PDF</span><input type="file" accept="application/pdf,.pdf" multiple data-files="${key}" aria-label="Choisir les ${key==='plan'?'plans':'dessins d’atelier'} PDF"></label><strong>Fichiers ajoutés (${arr.length})</strong>${filesHtml(arr,key)||'<small class="muted">Aucun fichier sélectionné</small>'}</section>`).join('')}</div>`:state.uploadStep===2?`<section class="card panel-pad"><h2>Vérifiez les documents</h2><p class="muted">${h($('#project-name')?.value||'')} · ${fmt(state.uploadPlans.length+state.uploadShop.length)} PDF · ${( [...state.uploadPlans,...state.uploadShop].reduce((n,f)=>n+f.size,0)/1048576).toFixed(1)} Mo au total</p><div class="table-wrap"><table><thead><tr><th>Document</th><th>Rôle</th><th>Pages</th><th>Taille</th></tr></thead><tbody>${[['plan',state.uploadPlans],['atelier',state.uploadShop]].flatMap(([role,arr])=>arr.map(f=>`<tr><td>${h(f.name)}</td><td>${h(files[role])}</td><td>${f.pages??'—'}</td><td>${(f.size/1048576).toFixed(1)} Mo</td></tr>`)).join('')}</tbody></table></div><p class="notice-panel spaced-notice">Les fichiers restent sur cet ordinateur. Limites : 150 Mo par PDF, 200 documents et 600 Mo par projet.</p></section>`:`<section class="card panel-pad"><h2>Projet importé</h2><p>Vos documents sont disponibles localement. Ouvrez le dossier pour les consulter ou démarrer une analyse.</p></section>`}<div id="upload-error" class="error-box" role="alert" hidden></div><div class="upload-footer"><small class="muted">PDF uniquement · Traitement local · aucun document envoyé à une API</small><div class="actions">${state.uploadStep===1?`<button type="button" class="button" data-action="cancel-upload">Annuler</button><button type="button" class="button primary" data-action="verify-upload">Vérifier les documents →</button>`:state.uploadStep===2?`<button type="button" class="button" data-action="back-upload">← Modifier les fichiers</button><button type="submit" class="button primary">Importer le projet</button>`:`<a class="button primary" href="#project/${encodeURIComponent(state.project)}">Ouvrir le projet →</a>`}</div></div></form>`}
async function inspectUpload(input,key){const selected=[...input.files];if(!selected.length)return;const err=$('#upload-error');err.hidden=true;const arr=key==='plan'?state.uploadPlans:state.uploadShop;for(const f of selected){if(f.type!=='application/pdf'&&!f.name.toLowerCase().endsWith('.pdf')){err.textContent=`${f.name} : seuls les fichiers PDF sont acceptés.`;err.hidden=false;continue}if(f.size>150*1048576){err.textContent=`${f.name} dépasse 150 Mo.`;err.hidden=false;continue}if([...state.uploadPlans,...state.uploadShop].reduce((n,x)=>n+x.size,0)+f.size>600*1048576){err.textContent='La taille totale dépasse 600 Mo.';err.hidden=false;continue}if(state.uploadPlans.length+state.uploadShop.length>=200){err.textContent='Un projet peut contenir au maximum 200 documents.';err.hidden=false;break}if(arr.some(x=>x.name===f.name&&x.size===f.size))continue;try{const meta=await readPdfMeta(f);arr.push(Object.assign(f,{pages:meta.pages}))}catch(e){err.textContent=`${f.name} : ${e.message}`;err.hidden=false}}input.value='';renderUpload()}
async function readPdfMeta(file){const src=URL.createObjectURL(file);try{const frame=document.createElement('iframe');frame.hidden=true;frame.src=src;document.body.append(frame);await new Promise((resolve,reject)=>{const t=setTimeout(()=>reject(Error('La vérification du PDF prend trop de temps.')),9000);frame.onload=()=>{clearTimeout(t);resolve()};frame.onerror=()=>{clearTimeout(t);reject(Error('PDF illisible ou protégé.'))}});const pages=Number(frame.contentDocument?.querySelector('#numPages')?.textContent)||Number(frame.contentDocument?.querySelector('input#pageNumber')?.max)||null;frame.remove();return {pages}}finally{URL.revokeObjectURL(src)}}
async function renderProject(id,routeId){const p=await api(`/projects/${encodeURIComponent(id)}`);if(routeId!==state.routeId)return;state.project=p;updateShell('project',p.name);const runs=completedRuns(id),latest=runs[0],tab=state.projectTab;$('#view').innerHTML=pageHeading(p.name,`${fmt(p.documents.length)} documents · ${fmt(p.pages)} pages · fichiers conservés localement`,`<button class="button primary" data-action="analyse" ${activeJob()?'disabled':''}>Lancer une analyse →</button>`)+`<div class="tabs" role="tablist"><button class="tab ${tab==='Documents'?'active':''}" data-project-tab="Documents" role="tab" aria-selected="${tab==='Documents'}">Documents <b>${p.documents.length}</b></button><button class="tab ${tab==='Analyses'?'active':''}" data-project-tab="Analyses" role="tab" aria-selected="${tab==='Analyses'}">Analyses <b>${runs.length}</b></button><button class="tab ${tab==='Révision'?'active':''}" data-project-tab="Révision" role="tab" aria-selected="${tab==='Révision'}">Révision</button></div>`+(tab==='Documents'?renderDocumentTab(p):tab==='Analyses'?renderAnalysisTab(runs):latest?`<div class="notice-panel section-notice">Dernière analyse : ${h(runDate(latest.created_at))} · ${fmt(latest.statistics.pages_processed)} / ${fmt(latest.statistics.pages_total)} pages lues</div><button class="button primary" data-open-run="${latest.id}">Ouvrir la révision →</button>`:`<div class="empty"><h2>Aucune révision disponible</h2><p>Lancez une analyse pour examiner les observations.</p><button class="button primary" data-action="analyse">Analyser le projet</button></div>`);if(tab==='Documents'&&p.documents.some(d=>d.id===state.docId))await renderDocPreview(state.docId,state.docPage)}
function renderDocumentTab(p){const docs=p.documents.filter(d=>state.docRole==='all'||d.role===state.docRole);if(!docs.some(d=>d.id===state.docId))state.docId=docs[0]?.id||null;return `<div class="document-layout document-layout-spaced"><section class="card document-list"><div class="toolbar"><div class="tabs document-role-tabs"><button class="tab ${state.docRole==='all'?'active':''}" data-doc-role="all">Tous ${p.documents.length}</button><button class="tab ${state.docRole==='plan'?'active':''}" data-doc-role="plan">Plans ${p.documents.filter(x=>x.role==='plan').length}</button><button class="tab ${state.docRole==='atelier'?'active':''}" data-doc-role="atelier">Atelier ${p.documents.filter(x=>x.role==='atelier').length}</button></div><input class="input search" type="search" id="doc-search" placeholder="Rechercher un document…" aria-label="Rechercher un document"></div><div class="table-wrap"><table><thead><tr><th>Nom du fichier</th><th>Rôle</th><th>Pages</th><th>Lecture</th></tr></thead><tbody>${docs.map(d=>`<tr data-doc-row="${d.id}" class="${d.id===state.docId?'selected':''}"><td><button class="text-action" data-doc="${d.id}">${h(d.name)}</button><span class="sub">${(d.bytes/1048576).toFixed(1)} Mo</span></td><td><span class="role ${d.role}">${h(d.role==='plan'?'Plan':'Atelier')}</span></td><td>${fmt(d.pages)}</td><td><span class="read-state">${d.role==='plan'?'● Texte ou OCR':'● Texte ou OCR'}</span></td></tr>`).join('')}</tbody></table></div></section><section class="card document-preview"><div id="doc-preview"><div class="empty">Choisissez un document pour le consulter.</div></div></section></div>`}
async function renderDocPreview(id,page=1){const d=state.project?.documents.find(x=>x.id===id);if(!d)return;state.docId=id;state.docPage=page;const target=$('#doc-preview');if(!target)return;target.innerHTML=`<div class="viewer-tools"><strong>${h(d.name)}</strong><span><button data-doc-page="-1" aria-label="Page précédente">‹</button> ${page} / ${d.pages} <button data-doc-page="1" aria-label="Page suivante">›</button></span></div><div class="viewer-tools"><button data-doc-zoom="-10" aria-label="Zoom arrière">−</button><span>${state.docZoom}%</span><button data-doc-zoom="10" aria-label="Zoom avant">＋</button><a class="button compact" href="/api/documents/${d.id}/pdf#page=${page}" target="_blank" rel="noopener">Ouvrir la source ↗</a></div><div class="preview-frame"><img src="${imagePreview(id,page,state.docZoom/100)}" alt="Page ${page} du document ${h(d.name)}" class="zoomed-page zoom-${state.docZoom}"></div><div class="doc-info"><strong>Informations du document</strong><div class="doc-info-grid"><span><small>Rôle</small>${h(files[d.role])}</span><span><small>Pages</small>${fmt(d.pages)}</span><span><small>Taille</small>${(d.bytes/1048576).toFixed(1)} Mo</span><span><small>Lecture</small>À analyser</span></div></div>`}
function renderAnalysisTab(runs){return runs.length?`<section class="card analysis-history"><div class="table-wrap"><table><thead><tr><th>Date</th><th>Périmètre</th><th>Pages lues</th><th>Observations</th><th></th></tr></thead><tbody>${runs.map(j=>`<tr><td>${h(runDate(j.created_at))}</td><td>${h({complete:'Complet',sample:'Aperçu OCR',native:'Texte natif'}[j.request.profile])}</td><td>${fmt(j.statistics.pages_processed)} / ${fmt(j.statistics.pages_total)}</td><td>${fmt(j.statistics.results)} observations</td><td><button class="button compact" data-open-run="${j.id}">Ouvrir la révision →</button></td></tr>`).join('')}</tbody></table></div></section>`:`<div class="empty"><h2>Aucune analyse terminée</h2><p>Lancez une analyse pour créer la première révision.</p><button class="button primary" data-action="analyse">Lancer l’analyse</button></div>`}
function renderAnalysisForm(p){const j=activeJob();return `${pageHeading('Analyser le projet',h(p.name))}${j?`<div class="notice-panel warning">Une autre analyse est en cours. Terminez-la avant d’en démarrer une nouvelle.</div>`:''}<form id="analysis-form" class="card panel-pad" novalidate><fieldset class="analysis-options" ${j?'disabled':''}><legend class="eyebrow">PÉRIMÈTRE DE LECTURE</legend><label class="field"><span><input type="radio" name="profile" value="complete" checked> Analyse complète</span><small>Texte PDF et OCR local sur les pages qui en ont besoin.</small></label><label class="field"><span><input type="radio" name="profile" value="sample"> Aperçu</span><small>Texte PDF et OCR sur un maximum de 4 pages.</small></label><label class="field"><span><input type="radio" name="profile" value="native"> Texte natif seulement</span><small>Ignore les pages sans texte natif.</small></label></fieldset><div class="notice-panel section-notice">Le premier passage OCR peut durer plusieurs minutes. Les pages lues sont mises en cache ; les annotations incertaines restent à examiner.</div><div class="dialog-actions"><a href="#project/${encodeURIComponent(p.id)}" class="button">Annuler</a><button class="button primary" type="submit" ${j?'disabled':''}>Démarrer l’analyse →</button></div><div id="analysis-error" class="error-box" hidden></div></form>`}
function pipeline(job){const stage=job?.stage||'reading',items=[['reading','Lire les documents','Extraction du texte et OCR local'],['matching','Rapprocher les éléments','Association prudente des annotations'],['reporting','Préparer les rapports','PDF et JSON par feuillet']];return `<div class="pipeline">${items.map(([id,title,desc],i)=>{const done=items.findIndex(x=>x[0]===stage)>i,active=id===stage;return `<div class="pipeline-row ${done?'done':''} ${active?'active':''}"><i class="pipeline-icon">${done?'✓':i+1}</i><div><strong>${title}</strong><small class="sub">${desc}</small></div><span class="sub pipeline-status">${done?'Terminé':active?'En cours':'En attente'}</span></div>`}).join('')}</div>`}
function renderProgress(job){const project=projectById(job.project_id),ratio=job.total?Math.min(100,Math.round(100*job.current/job.total)):0,doc=project?.documents.find(x=>x.id===job.current_doc);updateShell('project','Analyse en cours');$('#view').innerHTML=pageHeading('Lecture des documents','Vous pouvez quitter cet écran ; l’analyse continue.',`<button class="button" data-project="${h(job.project_id)}">Retour au projet</button>`)+`<div class="progress-layout"><section class="card progress-panel" data-job-panel="${job.id}"><div class="progress-numbers"><strong>${fmt(job.current)} / ${fmt(job.total)} pages</strong><b>${ratio} %</b></div><div class="progress-track" data-progress="${ratio}" role="progressbar" aria-label="Pages analysées" aria-valuenow="${ratio}" aria-valuemin="0" aria-valuemax="100"><div class="dynamic-fill"></div></div><div class="eyebrow">FICHIER EN COURS</div><strong>${h(doc?.name||job.project_name)} · page ${fmt(job.current_page||job.current)}</strong>${pipeline(job)}<div class="activity-mini"><strong>État de lecture</strong><p>${fmt(job.annotations)} annotations extraites · ${fmt(job.ocr_pages)} pages OCR</p><p>${h(job.message)}</p></div><button class="button danger" data-action="stop-job" data-job="${job.id}">Arrêter l’analyse</button><div class="notice-panel spaced-notice">Les heures restantes ne sont pas estimées. La progression suit les pages réellement parcourues.</div></section><section class="card progress-viewer"><div id="running-preview"><div class="empty"><div class="spinner" aria-hidden="true"></div><p>Préparation de l’aperçu…</p></div></div></section></div>`;if(doc)renderJobPreview(doc,job.current_page||1)}
function renderJobPreview(doc,page){const t=$('#running-preview');if(!t)return;t.innerHTML=`<div class="viewer-tools"><strong>${h(doc.name)}</strong><span>Page ${fmt(page)} / ${fmt(doc.pages)} · ${status('running')}</span></div><div class="preview-frame"><img src="${imagePreview(doc.id,page,.8)}" alt="Page ${page} du document en cours d’analyse" loading="lazy"></div><div class="viewer-tools"><span>${h(doc.role==='plan'?'Plan de structure':'Dessin d’atelier')}</span><a target="_blank" rel="noopener" href="/api/documents/${doc.id}/pdf#page=${page}">Ouvrir la source ↗</a></div>`}
function makeParams(){return new URLSearchParams({...state.filter,limit:25})}
function resultTabs(stats){const c=stats.counts,total=stats.results??Object.values(c).reduce((sum,value)=>sum+(Number(value)||0),0);return `<div class="filter-tabs" role="group" aria-label="Filtrer les conclusions"><button class="filter-tab ${state.filter.status===''?'active':''}" data-status="">Tout <b>${fmt(total)}</b></button><button class="filter-tab ${state.filter.status==='non_conforme'?'active':''}" data-status="non_conforme">Écarts proposés <b>${fmt(c.non_conforme)}</b></button><button class="filter-tab ${state.filter.status==='a_verifier'?'active':''}" data-status="a_verifier">À vérifier <b>${fmt(c.a_verifier)}</b></button><button class="filter-tab ${state.filter.status==='conforme'?'active':''}" data-status="conforme">Accords partiels <b>${fmt(c.conforme)}</b></button></div>`}
async function renderReview(){const runs=completedRuns(),run=runs.find(j=>j.id===state.run)||runs[0];if(!run){updateShell('review','Révision');$('#view').innerHTML=pageHeading('Observations à examiner','Les propositions de comparaison et leurs sources apparaissent ici.')+`<div class="empty card"><h2>Aucune révision à afficher</h2><p>Choisissez un projet et lancez une analyse complète ou un aperçu.</p><a class="button primary" href="#projects">Voir les projets →</a></div>`;return}state.run=run.id;const stats=run.statistics;updateShell('review',`${run.project_name} / Révision`);$('#view').innerHTML=`<div class="review-page ${state.hideDecision?'decision-hidden':''}">${pageHeading('Observations à examiner',h(run.project_name),`<button class="button" data-open-reports="${run.id}">Voir les rapports →</button>`)}<div class="tabs"><label class="eyebrow analysis-label" for="run-select">ANALYSE</label><select class="input" id="run-select" aria-label="Choisir une analyse">${runs.map(j=>`<option value="${j.id}" ${j.id===run.id?'selected':''}>${h(runDate(j.created_at))} · ${h({complete:'Complète',sample:'Aperçu',native:'Texte natif'}[j.request.profile])}</option>`).join('')}</select></div>${resultTabs(stats)}<div class="coverage-line"><strong>${fmt(stats.pages_processed)} / ${fmt(stats.pages_total)} pages lues</strong> · ${fmt(stats.pages_error)} erreurs · Une page lue ne garantit pas toutes les correspondances.</div><div class="notice-panel warning">Les statuts du moteur sont des propositions. La couverture de lecture ne mesure pas la couverture de détection.</div><div class="card"><div class="toolbar"><input class="input search" id="result-search" type="search" aria-label="Rechercher par repère, feuillet ou texte" placeholder="Rechercher un repère…" value="${h(state.filter.q)}"><select class="input" id="family-filter" aria-label="Filtrer par famille"><option value="">Toutes les familles</option>${Object.entries(families).map(([k,v])=>`<option value="${k}" ${state.filter.family===k?'selected':''}>${v}</option>`).join('')}</select><select class="input" id="sheet-filter" aria-label="Filtrer par feuillet"><option value="">Tous les feuillets</option>${state.sheets.map(s=>`<option value="${h(s)}" ${state.filter.sheet===s?'selected':''}>${h(s)}</option>`).join('')}</select><select class="input" id="review-filter" aria-label="Filtrer les révisions"><option value="">Toute révision</option><option value="unreviewed" ${state.filter.review==='unreviewed'?'selected':''}>Non examinées</option><option value="confirme" ${state.filter.review==='confirme'?'selected':''}>Confirmées par un humain</option><option value="rejete" ${state.filter.review==='rejete'?'selected':''}>Rejetées par un humain</option><option value="a_verifier" ${state.filter.review==='a_verifier'?'selected':''}>À reprendre</option></select><button class="button compact" id="clear-search" ${!state.filter.q?'hidden':''}>Effacer</button></div><div id="result-table" aria-live="polite"><div class="skeleton-table"><i></i><i></i><i></i></div></div></div></div>`;await fetchResults()}
async function fetchResults(){state.controller?.abort();state.controller=new AbortController();const p=makeParams(),target=$('#result-table');if(!target)return;target.setAttribute('aria-busy','true');try{const r=await api(`/runs/${state.run}/results?${p}`,{signal:state.controller.signal});if(!target.isConnected)return;state.results=r.items;state.resultTotal=r.total;target.innerHTML=`<div class="table-wrap"><table><thead><tr><th>Repère</th><th>Feuillet</th><th>Famille</th><th>Observation automatique</th><th>Décision humaine</th><th></th></tr></thead><tbody>${r.items.map(x=>`<tr><td><strong>${h(x.element)}</strong></td><td class="mono">${h(x.sheet)}</td><td>${h(families[x.family]||x.family)}</td><td>${status(x.status)}<span class="sub">${h(x.reason)}</span></td><td>${x.review?status(x.review.decision):'<span class="sub">Non examinée</span>'}</td><td><button class="button compact" data-detail="${h(x.id)}">Examiner →</button></td></tr>`).join('')}</tbody></table>${!r.total?`<div class="empty"><h2>Aucune observation ne correspond</h2><p>Modifiez le texte ou les filtres pour élargir la recherche.</p><button class="button" data-action="reset-filters">Réinitialiser les filtres</button></div>`:''}</div><div class="pagination"><span>${fmt(r.total)} observations · ${r.total?`${fmt(r.offset+1)}–${fmt(Math.min(r.offset+r.limit,r.total))}`:'0'} affichées</span><div><button class="button compact" data-page="-1" ${r.offset===0?'disabled':''}>← Précédent</button><button class="button compact" data-page="1" ${r.offset+r.limit>=r.total?'disabled':''}>Suivant →</button></div></div>`}catch(e){if(e.name!=='AbortError')target.innerHTML=`<div class="error-box">${h(e.message)} <button class="button" data-action="retry">Réessayer</button></div>`}finally{target.removeAttribute('aria-busy')}}
function compareValues(plan,shop){const attrs=[['Diamètre',a=>a?.diametre],['Quantité',a=>a?.quantite],['Espacement',a=>a?.espacement_mm===null?'—':a.espacement_mm===undefined?'—':`${a.espacement_mm} mm`],['Longueur',a=>a?.longueur_mm===null?'—':a.longueur_mm===undefined?'—':`${a.longueur_mm} mm`]];const a=plan?.information.armature?.[0],b=shop?.information.armature?.[0];return attrs.map(([name,get])=>{const x=get(a),y=get(b);return {name,a:x??'—',b:y??'—',different:x!==null&&x!==undefined&&y!==null&&y!==undefined&&String(x)!==String(y)}})}
function sourcePane(records,side){
 const record=records.find(r=>r.information.source===side),label=files[side],zoom=state.paneZoom?.[side]||100;
 if(!record)return `<section class="compare-pane ${side}"><div class="pane-head"><strong>${h(label)}</strong><span>Source non établie</span></div><div class="empty"><h3>Correspondance à établir</h3><p>Aucune annotation suffisamment fiable pour afficher cette source.</p></div></section>`;
 const info=record.information,full=state.sourceMode==='page';
 return `<section class="compare-pane ${side}"><div class="pane-head"><div><span class="source-kicker">${side==='plan'?'RÉFÉRENCE':'FABRICATION'}</span><strong>${h(label)}</strong></div><a class="source-open" target="_blank" rel="noopener" href="/api/documents/${record.doc_id}/pdf#page=${info.page}" aria-label="Ouvrir le PDF ${h(label)}">PDF ↗</a></div>
 <div class="source-document"><strong title="${h(info.fichier)}">${h(info.fichier)}</strong><span>Page ${info.page} · ${h(info.feuillet)}</span></div>
 <div class="pane-controls"><span class="source-marker">Repère <strong>${h(info.element)}</strong></span><div class="zoom-controls"><button data-zoom="-25" data-side="${side}" aria-label="Réduire le zoom ${h(label)}">−</button><output data-zoom-label="${side}" aria-live="polite">${zoom}%</output><button data-zoom="25" data-side="${side}" aria-label="Augmenter le zoom ${h(label)}">＋</button><button data-zoom="reset" data-side="${side}" aria-label="Adapter ${h(label)}">Adapter</button></div></div>
 <div class="pdf-view ${full?'page-mode':'region-mode'}" data-pan="${side}" tabindex="0" aria-label="Zone de lecture ${h(label)}. Défilez ou faites glisser pour déplacer le dessin."><img draggable="false" data-pdf-pane="${side}" src="${imagePreview(record.doc_id,info.page,full?1.2:2,record.box.join(','),full)}" alt="${h(label)} · ${h(info.fichier)} · page ${info.page} · ${h(record.raw)}" class="zoomed-page zoom-${zoom}"></div>
 <div class="source-reading"><span>TEXTE EXTRAIT</span><strong>${h(record.raw)}</strong><small>À vérifier sur le dessin source</small></div></section>`
}
function updateSourceZoom(side,action){state.paneZoom??={plan:100,atelier:100};const next=action==='reset'?100:Math.max(50,Math.min(200,state.paneZoom[side]+Number(action)));for(const key of (state.zoomLinked===false?[side]:['plan','atelier'])){state.paneZoom[key]=next;const img=$(`[data-pdf-pane="${key}"]`),label=$(`[data-zoom-label="${key}"]`);if(img)img.className=`zoomed-page zoom-${next}`;if(label)label.textContent=`${next}%`;if(action==='reset'){const pane=$(`[data-pan="${key}"]`);if(pane){pane.scrollTop=0;pane.scrollLeft=0}}}}

function currentDetailRecords(){const records=state.detail.records||[];if(!state.detail.pairing_candidates?.length)return records;const selected=state.detail.pairing_candidates[state.candidate];if(!selected)return records;const plan=records.find(r=>r.information.source==='plan'&&r.information.id===selected.plan_id)||records.find(r=>r.information.source==='plan');return [...records.filter(r=>r.information.source==='atelier'),...(plan?[plan]:[]),selected.record]}
function renderDetail(){updateShell('detail','Bureau de révision');const d=state.detail,records=currentDetailRecords(),plan=records.find(r=>r.information.source==='plan'),shop=records.find(r=>r.information.source==='atelier'),values=compareValues(plan,shop),candidate=d.pairing_candidates?.[state.candidate];$('#view').innerHTML=`<div class="review-page ${state.hideDecision?'decision-hidden':''}">${pageHeading(`${h(d.element)} · ${h(families[d.family]||d.family)} · ${h(d.sheet)}`,`${h(d.project_name||projectById(state.overview.jobs.find(j=>j.id===state.run)?.project_id)?.name||'Projet')} / comparaison des sources`, `<div class="detail-nav"><button class="button compact" data-detail-nav="previous" ${!d.previous?'disabled':''} aria-label="Observation précédente">←</button><span>Observation ${fmt(d.position)} / ${fmt(d.total)}</span><button class="button compact" data-detail-nav="next" ${!d.next?'disabled':''} aria-label="Observation suivante">→</button><button class="button compact" data-action="back-review">Fermer</button></div>`)}<div class="review-tools"><div class="view-segments" role="group" aria-label="Cadrage des sources"><button data-source-mode="region" aria-pressed="${state.sourceMode!=='page'}">Zone repérée</button><button data-source-mode="page" aria-pressed="${state.sourceMode==='page'}">Page entière</button></div><span class="review-pan-hint">Faites glisser le dessin pour le déplacer</span><div class="review-tool-actions"><button class="button compact" data-zoom-link aria-pressed="${state.zoomLinked!==false}">${state.zoomLinked===false?'Zooms indépendants':'Zooms liés'}</button><button class="button compact" data-toggle-decision aria-expanded="${!state.hideDecision}">${state.hideDecision?'Afficher la décision':'Agrandir les plans'}</button></div></div><div class="compare-shell"><div class="compare-panes">${sourcePane(records,'plan')}${sourcePane(records,'atelier')}</div><aside class="inspect"><div class="inspector-title"><span class="eyebrow">OBSERVATION À RÉVISER</span><h2>Votre décision</h2></div><div class="status-row">Proposition du moteur ${status(d.status)}</div><table><thead><tr><th>Attribut</th><th>Plan</th><th>Atelier</th></tr></thead><tbody>${values.map(v=>`<tr><td>${v.name}</td><td class="values ${v.different?'mismatch':''}">${h(v.a)}</td><td class="values ${v.different?'mismatch':''}">${h(v.b)}</td></tr>`).join('')}</tbody></table><details class="review-evidence"><summary>Indices de correspondance</summary><ul class="evidence-list">${plan&&shop&&plan.information.element===shop.information.element?'<li>Repère identique</li>':''}${plan&&shop&&plan.information.feuillet===shop.information.feuillet?'<li>Feuillet identique</li>':''}<li>Documents et pages affichés dans les sources</li></ul></details>${candidate?`<div class="inspector-notice">Suggestion expérimentale · ${candidate.warnings.map(h).join(' · ')||'Identité à vérifier sur les deux dessins'}</div><div class="candidate-switch"><button class="button compact" data-candidate="-1" ${state.candidate<=0?'disabled':''}>←</button><span>Candidat ${state.candidate+1} / ${d.pairing_candidates.length}</span><button class="button compact" data-candidate="1" ${state.candidate+1>=d.pairing_candidates.length?'disabled':''}>→</button></div>`:''}${d.review?`<div class="notice-panel">Dernière révision : ${status(d.review.decision)}<p>${h(d.review.note)}</p><small>${h(runDate(d.review.at))}</small></div>`:''}<label class="field" for="review-note">Note de révision <small>Facultatif</small><textarea id="review-note" maxlength="2000" placeholder="Ce que vous avez vérifié, les écarts constatés…">${h(state.reviewDraft??d.review?.note??'')}</textarea></label><div class="decision-grid"><button class="button primary" data-review="confirme">Confirmer ma révision</button><button class="button" data-review="rejete">Rejeter la proposition</button><button class="button" data-review="a_verifier">À reprendre</button></div><p class="decision-note">Cette décision humaine reste distincte de la conclusion automatique.</p><details class="review-evidence"><summary>Documents sources</summary><div class="findings-list">${(d.records||[]).map((r,i)=>`<a class="finding-link" target="_blank" rel="noopener" href="/api/documents/${r.doc_id}/pdf#page=${r.information.page}"><span>${h(r.information.fichier)} · p.${r.information.page}</span><span>Ouvrir ↗</span></a>`).join('')}</div></details><div id="review-error" class="error-box" hidden></div></aside></div></div>`}
async function openDetail(id){
 state.reviewDrafts??={};if(state.detail&&state.reviewDraft!==null&&state.reviewDraft!==undefined)state.reviewDrafts[`${state.run}:${state.detail.id}`]=state.reviewDraft;
 $('#view').setAttribute('aria-busy','true');try{const detail=await api(`/runs/${state.run}/results/${encodeURIComponent(id)}`);state.detail=detail;state.reviewDraft=state.reviewDrafts[`${state.run}:${id}`]??null;state.paneZoom={plan:100,atelier:100};state.candidate=0;renderDetail()}catch(e){showError(e.message)}finally{$('#view').removeAttribute('aria-busy')}
}

function renderReports(){
 const runs=completedRuns(),run=runs.find(j=>j.id===state.run)||runs[0];
 if(!run){updateShell('reports','Rapports');$('#view').innerHTML=pageHeading('Rapports de révision','Vos observations, réunies par feuillet.')+`<div class="empty card"><h2>Aucun rapport disponible</h2><p>Lancez une analyse pour préparer votre premier rapport de révision.</p><a class="button primary" href="#projects">Voir les projets →</a></div>`;return}
 state.run=run.id;updateShell('reports',`${run.project_name} / Rapports`);
 const sheets=state.reportInfo?.sheets||[],selected=sheets.find(x=>x.id===state.reportSheet),counts=run.statistics.counts;
 $('#view').innerHTML=pageHeading('Rapports de révision',`${run.project_name} · Consultez les preuves et composez votre export par feuillet.`,`<a class="button" href="/api/runs/${run.id}/download/informations.json">Exporter les données JSON ↓</a>`)+`
 <div class="reports-layout"><section class="card report-controls">
 <div class="report-control-head"><label class="field">Analyse de référence<select class="input" id="report-run">${runs.map(j=>`<option value="${j.id}" ${j.id===run.id?'selected':''}>${h(j.project_name)} · ${h(runDate(j.created_at))} · ${h({complete:'Complète',sample:'Aperçu',native:'Texte natif'}[j.request.profile])}</option>`).join('')}</select><small>${fmt(run.statistics.pages_processed)} / ${fmt(run.statistics.pages_total)} pages lues</small></label>
 <div class="report-summary"><div>${fmt(counts.non_conforme)}<small>écarts proposés</small></div><div>${fmt(counts.a_verifier)}<small>à vérifier</small></div><div>${fmt(counts.conforme)}<small>accords partiels</small></div></div></div>
 <div class="report-selection-head"><div class="section-head"><h2>Feuillets du rapport</h2><small>${fmt(sheets.length)} FEUILLETS</small></div><input class="input" id="report-search" type="search" value="${h(state.reportQuery||'')}" placeholder="Rechercher un feuillet…" aria-label="Rechercher un feuillet"><div class="report-selection-actions"><span id="selection-count">${fmt(state.selectedSheets.size)} sélectionnés</span><span><button class="text-action" data-report-select="all" ${state.reportInfo?'':'disabled'}>Tout sélectionner</button> · <button class="text-action" data-report-select="none" ${state.reportInfo?'':'disabled'}>Aucun</button></span></div></div>
 <div class="checklist">${sheets.map(sheet=>`<div class="report-sheet ${sheet.id===state.reportSheet?'active':''}" data-report-row="${h(sheet.name.toLowerCase())}"><input type="checkbox" aria-label="Inclure ${h(sheet.name)} dans l’export" data-sheet-check="${sheet.id}" ${state.selectedSheets.has(sheet.id)?'checked':''}><button class="sheet-preview-button" data-report-preview="${sheet.id}" aria-label="Aperçu du feuillet ${h(sheet.name)}" ${sheet.id===state.reportSheet?'aria-current="true"':''}><span class="sheet-name">${h(sheet.name)}<span>${fmt(sheet.total)} obs.</span></span><span class="sheet-meta"><em>${fmt(sheet.counts.non_conforme||0)} écarts</em> · ${fmt(sheet.counts.a_verifier||0)} à vérifier · ${fmt(sheet.reviewed)} révisions</span></button></div>`).join('')}<div class="report-empty-search" id="report-no-results" hidden>Aucun feuillet ne correspond à votre recherche.</div></div>
 <div class="report-export"><button class="button primary" data-action="download-selected" ${state.selectedSheets.size?'':'disabled'}>Télécharger la sélection ↓</button><a class="button" href="/api/runs/${run.id}/download/comparaisons.json">Exporter les comparaisons JSON</a><p class="muted">Un PDF par feuillet. Les propositions du moteur et vos décisions restent identifiables dans chaque rapport.</p></div></section>
 <section class="report-preview-wrap" aria-label="Aperçu du rapport"><div class="report-preview-title"><div><strong>${h(selected?.name||'Aperçu du rapport')}</strong><small>${h(run.project_name)} · Document de révision</small></div><button class="button compact" data-action="download-one" ${state.reportSheet?'':'disabled'}>Télécharger ce PDF ↓</button></div><div class="report-preview-tools"><button class="button compact" data-report-page="-1" aria-label="Page de rapport précédente" ${state.reportPage<=1?'disabled':''}>←</button><span>Page ${state.reportPage} / ${state.reportPages}</span><button class="button compact" data-report-page="1" aria-label="Page de rapport suivante" ${state.reportPage>=state.reportPages?'disabled':''}>→</button></div><div class="report-paper">${state.reportSheet?`<img class="report-preview-img" id="report-preview-img" src="/api/runs/${run.id}/reports/${state.reportSheet}/preview?page=${state.reportPage}" alt="Aperçu de la page ${state.reportPage} du rapport ${h(selected?.name||'sélectionné')}">`:`<div class="empty"><h2>Choisissez un feuillet</h2><p>Ouvrez un feuillet à gauche pour consulter ses observations.</p></div>`}</div></section></div>`;applyReportFilter();
}
function applyReportFilter(){const q=(state.reportQuery||'').toLocaleLowerCase('fr-CA').trim();let visible=0;$$('[data-report-row]').forEach(row=>{row.hidden=!row.dataset.reportRow.includes(q);if(!row.hidden)visible++});const empty=$('#report-no-results');if(empty)empty.hidden=visible>0}
function updateReportSelection(){const count=$('#selection-count');if(count)count.textContent=`${fmt(state.selectedSheets.size)} sélectionnés`;const download=$('[data-action="download-selected"]');if(download)download.disabled=!state.selectedSheets.size}

async function loadReports(){const info=await api(`/runs/${state.run}/reports`);state.reportInfo=info;if(!state.reportInfo.sheets.some(x=>x.id===state.reportSheet))state.reportSheet=(info.sheets.find(s=>(s.counts.non_conforme||0)>0)||info.sheets[0])?.id||null;if(state.reportLoadedRun!==state.run){state.selectedSheets=new Set(info.sheets.map(s=>s.id));state.reportQuery='';state.reportLoadedRun=state.run;}state.reportPage=1;renderReports();await refreshReportPreview()}
async function refreshReportPreview(){const img=$('#report-preview-img');if(!img||!state.reportSheet)return;try{const resp=await api(`/runs/${state.run}/reports/${state.reportSheet}/preview?page=${state.reportPage}`,{raw:true});state.reportPages=Number(resp.headers.get('X-Report-Pages'))||1;const blob=await resp.blob();img.src=URL.createObjectURL(blob);img.onload=()=>URL.revokeObjectURL(img.src);const label=$('.report-preview-tools span');if(label)label.textContent=`Page ${state.reportPage} / ${state.reportPages}`;const buttons=$$('.report-preview-tools button');if(buttons[0])buttons[0].disabled=state.reportPage<=1;if(buttons[1])buttons[1].disabled=state.reportPage>=state.reportPages}catch(e){if(e.message.includes('rapport'))state.reportPage=Math.max(1,state.reportPage-1);else showError(e.message)}}
function renderSettings(){const c=state.overview.settings,hw=state.overview.hardware;updateShell('settings','Réglages');const total=hw.vram_total||0,free=hw.vram_free||0,used=total?Math.max(0,total-free):0,pct=total?used/total*100:0;$('#view').innerHTML=pageHeading('Lecture et traitement','Ces réglages s’appliquent à la prochaine analyse.')+`<div class="settings-layout"><form id="settings-form" class="card settings-form" novalidate><div class="settings-section settings-first"><h2>Lecture des documents</h2><label class="field">Moteur OCR<select class="input" name="ocr_engine"><option value="rapidocr" ${c.ocr_engine==='rapidocr'?'selected':''}>RapidOCR · PP-OCRv4</option><option value="easyocr" ${c.ocr_engine==='easyocr'?'selected':''}>EasyOCR · CRAFT + CRNN</option></select><small>Modèles locaux · résultats à vérifier dans les documents.</small></label><label class="checkbox-row"><input type="checkbox" name="ocr_rotations" ${c.ocr_rotations?'checked':''}><span>Lire aussi les annotations tournées<small>Lectures complémentaires à 90° et 270°.</small></span></label></div><div class="settings-section"><h2>Calcul</h2><label class="field">Processeur<select class="input" name="device"><option value="auto" ${c.device==='auto'?'selected':''}>Automatique · GPU si disponible</option><option value="cuda" ${c.device==='cuda'?'selected':''}>GPU NVIDIA · CUDA requis</option><option value="cpu" ${c.device==='cpu'?'selected':''}>CPU uniquement</option></select></label><label class="checkbox-row"><input type="checkbox" name="pairing_assistance" ${c.pairing_assistance?'checked':''}><span>Proposer des correspondances expliquées <span class="status check">Expérimental</span><small>Les propositions ne changent pas la conclusion automatique ; vérifiez les sources.</small></span></label><details><summary>Réglages avancés · lot ${c.batch_size} · ${c.dpi} dpi · détecteur ${c.canvas_size}px</summary><div class="field-grid"><label class="field">Lot OCR<select class="input" name="batch_size">${[1,4,8,16,32,64].map(x=>`<option ${c.batch_size===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Résolution<select class="input" name="dpi">${[96,120,144,180,216].map(x=>`<option value="${x}" ${c.dpi===x?'selected':''}>${x} dpi</option>`).join('')}</select></label><label class="field">Taille du détecteur<select class="input" name="canvas_size">${[1280,1920,2560,3200].map(x=>`<option ${c.canvas_size===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Confiance OCR minimale<input class="input" type="number" name="ocr_confidence" min="0.05" max="0.95" step="0.05" value="${c.ocr_confidence}"></label></div></details><div class="notice-panel">Le texte natif est extrait sans OCR. La lecture OCR utilise le GPU quand il est disponible. En cas de mémoire insuffisante, le moteur peut basculer sur CPU.</div></div><div class="form-actions"><div id="settings-error" class="error-box" hidden></div><button class="button primary" type="submit">Enregistrer les réglages</button></div></form><div><section class="card hardware-card"><div class="hardware-glyph" aria-hidden="true">▤</div><h2>Matériel disponible</h2><strong>${h(hw.device)}</strong><div class="device-spec"><span>CUDA</span><strong>${hw.cuda?'Disponible':'Indisponible'}</strong></div><div class="device-spec"><span>Mémoire vidéo</span><strong>${total?(total/1073741824).toFixed(1)+' Go':'—'}</strong></div><div class="resource-track" role="progressbar" aria-label="Mémoire vidéo utilisée" aria-valuenow="${pct.toFixed(0)}" aria-valuemin="0" aria-valuemax="100" data-progress="${pct.toFixed(0)}"><span class="dynamic-fill"></span></div><small>${total?(used/1073741824).toFixed(1)+' Go utilisés · '+(free/1073741824).toFixed(1)+' Go libres':'Mémoire indisponible'}</small><div class="device-spec"><span>PyTorch</span><strong>${h(hw.torch||'—')}</strong></div><p class="small muted">La mémoire libre inclut les autres applications.</p></section><section class="card hardware-card"><h2>Modèles installés</h2><div class="model-item"><strong>PP-OCRv4</strong><small>RapidOCR · reconnaissance de texte imprimé</small></div><div class="model-item"><strong>CRAFT + CRNN Latin</strong><small>EasyOCR · détection et reconnaissance de texte</small></div><p class="notice-panel spaced-notice">Aucun appel à une API d’IA externe.</p></section></div></div>`}
function renderGuide(){updateShell('guide','Guide du défi');const bars=[['Détection des écarts',30],['Extraction JSON',20],['Rapport',15],['Technique',15],['Robustesse · 5 familles',10],['Démonstration',10]];$('#view').innerHTML=pageHeading('Bien conduire une révision','Du plan de référence aux décisions appuyées par leurs preuves.')+`<div class="guide-layout"><nav class="guide-nav" aria-label="Dans cette page"><a href="#workflow">Étapes</a><a href="#legend">Statuts</a><a href="#score">Évaluation</a><a href="#privacy">Confidentialité</a></nav><div class="guide-main"><section id="workflow"><h2>Étapes de travail</h2>${[['Importer','Séparez les plans de référence des dessins de fabrication.'],['Analyser','Lisez les PDF et les pages sans texte avec l’OCR local.'],['Vérifier les preuves','Examinez les deux sources avant d’enregistrer votre décision.'],['Exporter par feuillet','Téléchargez un rapport PDF pour chacun des feuillets retenus.']].map((x,i)=>`<div class="guide-step"><i>${i+1}</i><strong>${x[0]}<small>${x[1]}</small></strong></div>`).join('')}</section><section id="legend" class="guide-section-spaced"><h2>Statuts de révision</h2><p class="small muted">La conclusion automatique et la décision humaine restent distinctes.</p><div class="legend-grid">${[['Écart proposé','Une différence détectée par le moteur. Vérifiez les deux sources.','proposed'],['À vérifier','La correspondance ou la lecture manque de certitude.','check'],['Accord partiel','Les valeurs lues concordent ; aucune validation globale.','partial'],['Révision confirmée','Un réviseur a confirmé sa propre décision.','confirmed']].map(([a,b,c])=>`<div class="legend-card"><span class="status ${c}">${a}</span><small>${b}</small></div>`).join('')}</div></section><section id="privacy" class="guide-section-spaced"><h2>Confidentialité et traitement local</h2><div class="privacy-grid"><div class="privacy-card"><strong>Modèles locaux</strong><small>L’analyse se déroule sur cet ordinateur.</small></div><div class="privacy-card"><strong>Documents confidentiels</strong><small>Aucun PDF transmis à un service d’IA externe.</small></div><div class="privacy-card"><strong>Exports</strong><small>Les rapports et JSON restent confidentiels.</small></div></div></section></div><aside id="score" class="card score-card"><h2>Évaluation du défi</h2><small class="muted">Barème · 100 points</small>${bars.map(([n,v])=>`<div class="score-row"><span>${n}</span><strong>${v}</strong></div><div class="score-track" data-score="${v}"><span class="score-fill"></span></div>`).join('')}<p class="notice-panel spaced-notice">La formule détaillée n’est pas publiée. Aucun score de ce moteur n’a été mesuré sur le projet caché.</p></aside></div>`}

function showError(message){const e=$('#error');e.textContent=message;e.hidden=false}
function clearError(){const e=$('#error');e.hidden=true;e.textContent=''}
function confirmStop(id){state.stoppedJob=id;$('#confirm-dialog').showModal()}
function renderCurrent(){const {page,id}=routeParts();state.route=page;clearError();$('#view').setAttribute('aria-busy','true');try{if(page==='projects')renderProjects();else if(page==='upload')renderUpload();else if(page==='project')renderProject(id,++state.routeId);else if(page==='analyse'){const p=projectById(id);p?($('#view').innerHTML=renderAnalysisForm(p),updateShell('project','Analyser le projet')):showError('Projet introuvable.')}else if(page==='review'){renderReview()}else if(page==='detail'&&state.detail){renderDetail()}else if(page==='reports'){renderReports();loadReports().catch(e=>showError(e.message))}else if(page==='settings')renderSettings();else if(page==='guide')renderGuide();else location.hash='projects'}finally{$('#view').removeAttribute('aria-busy')}}
async function route(){await loadOverview();if(activeJob()&&routeParts().page==='progress'){renderProgress(activeJob());return}if(routeParts().page==='progress'){location.hash='projects';return}renderCurrent();schedulePoll()}
function schedulePoll(){clearTimeout(pollTimer);if(activeJob())pollTimer=setTimeout(poll,1700)}
async function poll(){const job=activeJob();if(!job)return;try{const fresh=await api(`/jobs/${job.id}`);const index=state.overview.jobs.findIndex(x=>x.id===job.id);if(index>=0)state.overview.jobs[index]=fresh;if(['running','queued'].includes(fresh.status)){if(routeParts().page==='progress')renderProgress(fresh);schedulePoll()}else{toast(fresh.status==='completed'?'Analyse terminée. Le rapport est disponible.':fresh.message);if(routeParts().page==='progress')location.hash=`project/${encodeURIComponent(fresh.project_id)}`;else route()}}catch(e){showError('Connexion interrompue. Nouvelle tentative…');pollTimer=setTimeout(poll,5000)}}
async function startAnalysis(id,profile){try{const result=await api(`/projects/${encodeURIComponent(id)}/analyse`,{method:'POST',body:JSON.stringify({profile,max_ocr_pages:4})});location.hash=`progress/${result.id}`}catch(e){showError(e.message)}}
function handleFiles(event){const key=event.target.dataset.files;inspectUpload(event.target,key)}
function clearFilters(){state.filter={q:'',status:'',family:'',sheet:'',review:'',offset:0};renderReview()}
// Template controls use delegated data-* actions because each view is replaced after navigation or requests.
document.addEventListener('click',async event=>{const el=event.target.closest('button,a,[data-doc]');if(!el)return;try{
 if(el.closest('.guide-nav')){event.preventDefault();document.querySelector(el.getAttribute('href'))?.scrollIntoView({block:'start'});return}
 if(el.matches('[data-close]')){el.closest('dialog')?.close();return}
 if(el.dataset.action==='import'){state.uploadPlans=[];state.uploadShop=[];state.uploadStep=1;state.project='';location.hash='upload';return}
 if(el.dataset.action==='cancel-upload'){location.hash='projects';return}
 if(el.dataset.removeFile){const files=el.dataset.removeFile==='plan'?state.uploadPlans:state.uploadShop;files.splice(Number(el.dataset.index),1);renderUpload();return}
 if(el.dataset.action==='verify-upload'){const name=$('#project-name')?.value.trim(),error=$('#upload-error');if(!name){error.textContent='Indiquez un nom de projet.';error.hidden=false;return}if(!state.uploadPlans.length||!state.uploadShop.length){error.textContent='Ajoutez au moins un plan et un dessin d’atelier.';error.hidden=false;return}state.project=name;state.uploadStep=2;renderUpload();return}
 if(el.dataset.action==='back-upload'){state.uploadStep=1;renderUpload();return}
 if(el.dataset.action==='analyse'){const p=state.project;location.hash=`analyse/${encodeURIComponent(p.id)}`;return}
 if(el.dataset.action==='stop-job'){confirmStop(el.dataset.job);return}
 if(el.dataset.action==='back-review'){location.hash='review';return}
 if(el.dataset.action==='reset-filters'){clearFilters();return}
 if(el.dataset.action==='retry'){fetchResults();return}
 if(el.dataset.action==='download-selected'){if(el.disabled)return;el.disabled=true;el.setAttribute('aria-busy','true');const label=el.textContent;el.textContent='Préparation de l’export…';try{const response=await api(`/runs/${state.run}/reports-export`,{method:'POST',body:JSON.stringify({sheets:[...state.selectedSheets]}),raw:true});const blob=await response.blob();const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='rapports-par-feuillet.zip';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);toast('Export prêt : téléchargement lancé.')}finally{el.disabled=!state.selectedSheets.size;el.removeAttribute('aria-busy');el.textContent=label}return}
 if(el.dataset.action==='download-one'&&state.reportSheet){window.open(`/api/runs/${state.run}/reports/${state.reportSheet}/pdf`,'_blank','noopener');return}
 if(el.dataset.project){location.hash=`project/${encodeURIComponent(el.dataset.project)}`;return}
 if(el.dataset.openRun){state.run=el.dataset.openRun;state.filter.offset=0;location.hash='review';return}
 if(el.dataset.openReports){state.run=el.dataset.openReports;location.hash='reports';return}
 if(el.dataset.detail){await openDetail(el.dataset.detail);location.hash='detail';return}
 if(el.dataset.detailNav){const id=el.dataset.detailNav==='previous'?state.detail.previous:state.detail.next;if(id){await openDetail(id);renderDetail()}return}
 if(el.dataset.review){const buttons=$$('[data-review]');buttons.forEach(x=>x.disabled=true);try{await api(`/runs/${state.run}/results/${state.detail.id}/review`,{method:'POST',body:JSON.stringify({decision:el.dataset.review,note:$('#review-note')?.value||''})});toast('Révision enregistrée.');await openDetail(state.detail.id)}catch(e){showError(e.message)}finally{buttons.forEach(x=>x.disabled=false)}return}
 if(el.dataset.candidate){state.candidate=Math.max(0,Math.min((state.detail.pairing_candidates?.length||1)-1,state.candidate+Number(el.dataset.candidate)));renderDetail();return}
 if(el.dataset.status!==undefined){state.filter.status=el.dataset.status;state.filter.offset=0;renderReview();return}
 if(el.dataset.page){state.filter.offset=Math.max(0,state.filter.offset+Number(el.dataset.page)*25);fetchResults();return}
 if(el.dataset.doc){await renderDocPreview(el.dataset.doc,state.docPage);return}
 if(el.dataset.docPage){const d=state.project?.documents.find(x=>x.id===state.docId);state.docPage=Math.max(1,Math.min(d?.pages||1,state.docPage+Number(el.dataset.docPage)));renderDocPreview(state.docId,state.docPage);return}
 if(el.dataset.docZoom){state.docZoom=Math.max(40,Math.min(140,state.docZoom+Number(el.dataset.docZoom)));renderDocPreview(state.docId,state.docPage);return}
 if(el.dataset.zoom!==undefined){updateSourceZoom(el.dataset.side,el.dataset.zoom);return}
 if(el.dataset.sourceMode){state.sourceMode=el.dataset.sourceMode;renderDetail();return}
 if(el.hasAttribute('data-zoom-link')){state.zoomLinked=state.zoomLinked===false;if(state.zoomLinked)state.paneZoom={plan:state.paneZoom?.plan||100,atelier:state.paneZoom?.plan||100};renderDetail();return}
 if(el.hasAttribute('data-toggle-decision')){state.hideDecision=!state.hideDecision;renderDetail();return}
 if(el.dataset.projectTab){state.projectTab=el.dataset.projectTab;renderProject(state.project.id,++state.routeId);return}
 if(el.dataset.docRole){state.docRole=el.dataset.docRole;renderProject(state.project.id,++state.routeId);return}
 if(el.dataset.reportPage){state.reportPage=Math.max(1,Math.min(state.reportPages,state.reportPage+Number(el.dataset.reportPage)));renderReports();refreshReportPreview();return}
 if(el.dataset.reportSelect){state.selectedSheets=new Set(el.dataset.reportSelect==='all'?(state.reportInfo?.sheets||[]).map(s=>s.id):[]);$$('[data-sheet-check]').forEach(x=>x.checked=state.selectedSheets.has(x.dataset.sheetCheck));updateReportSelection();return}
 if(el.dataset.reportPreview){state.reportSheet=el.dataset.reportPreview;state.reportPage=1;state.reportPages=1;renderReports();await refreshReportPreview();return}
 if(el.dataset.sheetCheck){return}
 if(el.id==='clear-search'){clearFilters();return}
 }catch(e){showError(e.message)}});
document.addEventListener('change',async event=>{const el=event.target;try{if(el.matches('[data-files]'))return handleFiles(event);if(el.id==='run-select'){state.run=el.value;state.filter.offset=0;renderReview();return}if(el.id==='family-filter'){state.filter.family=el.value;state.filter.offset=0;fetchResults();return}if(el.id==='sheet-filter'){state.filter.sheet=el.value;state.filter.offset=0;fetchResults();return}if(el.id==='review-filter'){state.filter.review=el.value;state.filter.offset=0;fetchResults();return}if(el.id==='report-run'){state.run=el.value;state.reportSheet=null;state.reportInfo=null;state.selectedSheets=new Set();await loadReports();return}if(el.dataset.sheetCheck){const id=el.dataset.sheetCheck;if(el.checked)state.selectedSheets.add(id);else state.selectedSheets.delete(id);updateReportSelection();return}if(el.id==='project-name'){state.project=el.value}}catch(e){showError(e.message)}});
document.addEventListener('input',event=>{const el=event.target;if(el.id==='review-note')state.reviewDraft=el.value;if(el.id==='report-search'){state.reportQuery=el.value;applyReportFilter();}if(el.id==='result-search'){state.filter.q=el.value;state.filter.offset=0;clearTimeout(searchTimer);searchTimer=setTimeout(fetchResults,300)}if(el.id==='doc-search'){const q=el.value.toLowerCase();$$('[data-doc-row]').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(q))}});
document.addEventListener('submit',async event=>{const form=event.target;event.preventDefault();try{if(form.id==='analysis-form'){const id=routeParts().id,profile=new FormData(form).get('profile');await startAnalysis(id,profile);return}if(form.id==='settings-form'){const data=new FormData(form),payload={...state.overview.settings,ocr_engine:data.get('ocr_engine'),device:data.get('device'),ocr_rotations:data.has('ocr_rotations'),pairing_assistance:data.has('pairing_assistance'),batch_size:Number(data.get('batch_size')),dpi:Number(data.get('dpi')),canvas_size:Number(data.get('canvas_size')),ocr_confidence:Number(data.get('ocr_confidence'))};const result=await api('/settings',{method:'POST',body:JSON.stringify(payload)});state.overview.settings=result.settings;toast('Réglages enregistrés pour la prochaine analyse.');return}if(form.id==='upload-form'){if(state.uploadStep!==2)return;const name=$('#project-name').value.trim(),formData=new FormData();formData.append('name',name);state.uploadPlans.forEach(x=>formData.append('plans',x,x.name));state.uploadShop.forEach(x=>formData.append('atelier',x,x.name));const response=await api('/import',{method:'POST',body:formData});state.project=response.id;state.uploadStep=3;toast('Projet importé localement.');renderUpload();return}}catch(e){const target=$('#analysis-error')||$('#settings-error')||$('#upload-error');if(target){target.textContent=e.message;target.hidden=false}else showError(e.message)}});
$('#confirm-stop')?.addEventListener('click',async()=>{const id=state.stoppedJob;$('#confirm-dialog')?.close();if(!id)return;try{await api(`/jobs/${id}/cancel`,{method:'POST'});toast('Arrêt demandé après la page en cours.')}catch(e){showError(e.message)}});
window.addEventListener('hashchange',()=>{window.scrollTo({top:0,behavior:'instant'});route().catch(e=>showError(e.message))});window.addEventListener('offline',()=>showError('Le service local est indisponible.'));
route().catch(e=>showError(e.message));

// Pointer panning leaves document scroll and keyboard navigation available.
let planDrag=null;
document.addEventListener('pointerdown',event=>{const pane=event.target.closest('[data-pan]');if(!pane||event.button!==0||event.pointerType==='touch')return;planDrag={pane,id:event.pointerId,x:event.clientX,y:event.clientY,left:pane.scrollLeft,top:pane.scrollTop};pane.setPointerCapture(event.pointerId);pane.classList.add('is-panning');event.preventDefault()});
document.addEventListener('pointermove',event=>{if(!planDrag||event.pointerId!==planDrag.id)return;planDrag.pane.scrollLeft=planDrag.left-(event.clientX-planDrag.x);planDrag.pane.scrollTop=planDrag.top-(event.clientY-planDrag.y)});
for(const type of ['pointerup','pointercancel','lostpointercapture'])document.addEventListener(type,()=>{if(planDrag)planDrag.pane.classList.remove('is-panning');planDrag=null});
